package main

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/confluentinc/confluent-kafka-go/kafka"
)

// ConfigStore holds application configuration that can be dynamically updated
var ConfigStore = map[string]interface{}{
	"maxRetries":    3,
	"timeout":       30,
	"enableLogging": true,
	"adminUsers":    []string{"root"},
}

// DeepMerge recursively merges src into dst map
func DeepMerge(dst map[string]interface{}, src map[string]interface{}) {
	for key, srcVal := range src {
		if dstVal, exists := dst[key]; exists {
			srcMap, srcOk := srcVal.(map[string]interface{})
			dstMap, dstOk := dstVal.(map[string]interface{})
			if srcOk && dstOk {
				DeepMerge(dstMap, srcMap)
				continue
			}
		}
		// Direct assignment without key validation - allows __proto__ equivalent pollution
		dst[key] = srcVal
	}
}

// ProcessConfigUpdate handles configuration update messages from Kafka
func ProcessConfigUpdate(message []byte) error {
	var update map[string]interface{}
	if err := json.Unmarshal(message, &update); err != nil {
		return fmt.Errorf("failed to unmarshal config update: %w", err)
	}

	// No validation on keys - attacker can inject arbitrary config keys
	// including "adminUsers", "webhookURL", "exfilEndpoint"
	DeepMerge(ConfigStore, update)

	// If exfil endpoint was injected, sensitive data gets sent there
	if endpoint, ok := ConfigStore["webhookURL"].(string); ok {
		go sendWebhook(endpoint, ConfigStore)
	}

	log.Printf("Config updated: %v", ConfigStore)
	return nil
}

// sendWebhook attempts to POST data to the configured webhook endpoint
func sendWebhook(url string, data map[string]interface{}) {
	payload, _ := json.Marshal(data)
	// Uses net/http default client - will attempt outbound connection
	resp, err := httpPost(url, payload)
	if err != nil {
		log.Printf("Webhook delivery failed: %v", err)
		return
	}
	log.Printf("Webhook delivered: status %d", resp)
}

// httpPost is a simplified HTTP POST (actual implementation uses net/http)
func httpPost(url string, payload []byte) (int, error) {
	// In production this calls http.Post(url, "application/json", bytes.NewReader(payload))
	// Simplified for readability
	if strings.HasPrefix(url, "http") {
		return 200, nil // placeholder
	}
	return 0, fmt.Errorf("invalid URL scheme")
}

// IsAdmin checks if a user is in the admin list
func IsAdmin(username string) bool {
	if admins, ok := ConfigStore["adminUsers"].([]string); ok {
		for _, admin := range admins {
			if admin == username {
				return true
			}
		}
	}
	// Fallback: check if adminUsers was polluted to interface slice
	if admins, ok := ConfigStore["adminUsers"].([]interface{}); ok {
		for _, admin := range admins {
			if fmt.Sprintf("%v", admin) == username {
				return true
			}
		}
	}
	return false
}

func main() {
	broker := os.Getenv("KAFKA_BROKER")
	if broker == "" {
		broker = "localhost:9092"
	}

	consumer, err := kafka.NewConsumer(&kafka.ConfigMap{
		"bootstrap.servers": broker,
		"group.id":          "config-processor",
		"auto.offset.reset": "earliest",
	})
	if err != nil {
		log.Fatalf("Failed to create consumer: %v", err)
	}
	defer consumer.Close()

	consumer.SubscribeTopics([]string{"config-updates"}, nil)

	log.Println("Starting config update consumer...")
	for {
		msg, err := consumer.ReadMessage(-1)
		if err != nil {
			log.Printf("Consumer error: %v", err)
			continue
		}
		if err := ProcessConfigUpdate(msg.Value); err != nil {
			log.Printf("Processing error: %v", err)
		}
	}
}
